cat > /tmp/probe/cna_pred.awk <<'EOF'
function pred(w,  n,l2,l1) {
  n=length(w); l1=substr(w,n,1); l2=(n>1?substr(w,n-1,1):"");
  if (l1=="y" && n>1 && l2!~/[aeiou]/) return substr(w,1,n-1) "ies";
  if (n>1 && substr(w,n-1,2)=="es") return w;
  if (l1=="s") return w "es";
  if (n>1 && (substr(w,n-1,2)=="ch" || substr(w,n-1,2)=="sh")) return w "es";
  return w "s";
}
BEGIN{FS="\t"}
{ p=pred($1); if (p != $2) printf "%s\t%s\t%s\n", $1, $2, p }
EOF
awk -f /tmp/probe/cna_pred.awk /tmp/probe/data/common-nouns-a.tsv | sort | tee /tmp/probe/cna_devs.txt | wc -l
